ferro_class_info!(Styles {
    markup: {
        namespace: "FerroUI.Styling",
        properties: [
            Resources: Rc<dyn IResourceDictionary> {
                get: |this: &Ref<Styles>| -> Rc<dyn IResourceDictionary> { this.resources().into() },
                try_set: |this: &Ref<Styles>, value: Rc<dyn IResourceDictionary>| {
                    match value.as_object().and_then(|object| object.to_ref().cast::<ResourceDictionary>()) {
                        Some(dictionary) => Ok(this.set_resources(dictionary)),
                        None => Err("The resource dictionary is not a ResourceDictionary."),
                    }
                }
            },
        ],
        methods: [
            try fn Add(Rc<dyn IStyle>) => |this: &Ref<Styles>, style: Rc<dyn IStyle>| {
                // A style that has an owner cannot be added to styles that have one.
                let owned = style.as_object().and_then(|o| o.to_ref().cast::<StyleBase>()).is_some_and(|s| s.owner().is_some());
                if owned && this.owner().is_some() {
                    return Err("The Style already has a parent.");
                }
                Ok(this.add(style))
            },
        ],
        events: [
            OwnerChanged(Option<BoxedValue>, EventArgs) => |this: &Ref<Styles>, handler: MarkupDelegate| {
                let sender = this.downgrade();
                this.owner_changed(move || {
                    handler.invoke(&[into_markup_value(sender.upgrade()), into_markup_value(EventArgs::EMPTY)]);
                })
            },
        ],
    },
});

